create table companies (id uuid primary key default gen_random_uuid(), name text, business_field text, employees int, revenue_range text, created_at timestamp default now());
create table capabilities (company_id uuid references companies(id) primary key, venture boolean default false, lab boolean default false, ip boolean default false, innobiz boolean default false, mainbiz boolean default false, iso boolean default false);
create table grants (id uuid primary key default gen_random_uuid(), title text, agency text, deadline date, max_amount text, source_url text, raw_content text, structured jsonb, matching_keywords text[], created_at timestamp default now());
create table readiness_scores (company_id uuid references companies(id), total int, base int, bonus int, breakdown jsonb, gaps jsonb, calculated_at timestamp default now(), primary key (company_id, calculated_at));
create table matches (company_id uuid references companies(id), grant_id uuid references grants(id), score int, reasons jsonb, created_at timestamp default now(), primary key (company_id, grant_id));
alter table companies enable row level security; alter table capabilities enable row level security; alter table grants enable row level security; alter table readiness_scores enable row level security; alter table matches enable row level security;
create policy "Allow all for dev" on companies for all using (true) with check (true); create policy "Allow all for dev" on capabilities for all using (true) with check (true); create policy "Allow all for dev" on grants for all using (true) with check (true); create policy "Allow all for dev" on readiness_scores for all using (true) with check (true); create policy "Allow all for dev" on matches for all using (true) with check (true);
